<template><section class="paper-card page-section"><div class="toolbar-line"><div><p class="eyebrow">INVENTORY</p><h1>馆藏日志</h1></div></div><el-form inline><el-form-item label="搜索"><el-input v-model="query.keyword" clearable placeholder="书名/ISBN"/></el-form-item><el-button @click="load">搜索</el-button></el-form><el-table :data="rows" v-loading="loading" border><el-table-column prop="book_title" label="图书"/><el-table-column prop="change_type" label="类型"/><el-table-column prop="before_stock" label="变动前"/><el-table-column prop="change_quantity" label="数量"/><el-table-column prop="after_stock" label="变动后"/><el-table-column prop="remark" label="备注"/><el-table-column prop="create_time" label="时间" min-width="160"/></el-table><div class="pagination-wrap"><el-pagination v-model:current-page="query.page" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{api}from'../api/library';const rows=ref([]),total=ref(0),loading=ref(false);const query=reactive({page:1,size:10,keyword:''});async function load(){loading.value=true;try{const r=await api.inventoryLogs(query);rows.value=r.data.list;total.value=r.data.total}finally{loading.value=false}}onMounted(load)</script>
